-- 2) Balance answer-option lengths: zonele-biogeografice (20/20 rewritten) and solurile-terrei (19/20 rewritten;
--    8ac2be87-fbe1-413d-a530-eda242a309ea already balanced, left untouched). correct_index unchanged in all cases.

-- biogeo_new.json
UPDATE question_translations SET options_json = '["Pentru că solurile feralsolice roșii de acolo sunt neobișnuit de fertile și hrănesc din belșug orice plantă.","Pentru că este cald și umed tot anul, fără un sezon nefavorabil care să oprească creșterea plantelor.","Pentru că se află la altitudine mare, unde răcoarea constantă ajută la apariția a tot mai multe specii noi.","Pentru că iarna lungă și geroasă elimină speciile slabe, lăsând loc doar celor mai rezistente și numeroase."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a01' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Are dreptate: un sol gros și roșu este, prin însăși culoarea lui, un semn sigur de fertilitate ridicată.","Culoarea roșie arată o cantitate mare de humus acumulat, deci un sol bogat în substanțe hrănitoare.","Ploile bogate spală permanent substanțele hrănitoare, iar rezerva de hrană a pădurii stă în vegetație, nu în sol.","Solul este de fapt foarte subțire acolo, prea firav ca să susțină o pădure atât de deasă și de înaltă."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a02' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Fiindcă solul este prea sărat pentru copaci, iar sarea din adânc oprește creșterea rădăcinilor lemnoase.","Fiindcă temperaturile sunt prea scăzute pentru pădure, deși savana se află aproape de Ecuator, unde ar trebui să fie cald.","Fiindcă alternanța dintre un sezon ploios și unul secetos nu îngăduie o pădure deasă, ci ierburi cu arbori răzleți.","Fiindcă oamenii au tăiat pădurea inițială de mult timp, iar ierburile au ocupat treptat locul rămas gol."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a03' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Leii nu ar fi afectați câtuși de puțin, pentru că, la nevoie, ei pot mânca și plante uscate.","Leii s-ar muta pur și simplu în pădurea ecuatorială, unde hrana rămâne mereu din belșug.","Leii ar începe să pască iarbă uscată în locul cărnii, adaptându-și rapid felul de hrănire.","Numărul erbivorelor ar scădea, deci ar scădea și leii, fiindcă fauna depinde de vegetație."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a04' AND locale = 'ro';
UPDATE question_translations SET options_json = '["La vara caldă și secetoasă, ca să piardă cât mai puțină apă prin frunzele lor mici și cerate.","La gerul aspru al iernii, care în zona mediteraneană ține luni întregi și îngheață solul.","La lipsa de lumină solară din pădurile dese care umbresc permanent tufișurile de dedesubt.","La nevoia de a crește foarte repede, înainte ca alte plante să le ia locul sub soare."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a05' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Fiindcă în taiga nu este niciodată frig, iar coniferele nu au niciun motiv să-și piardă acele iarna.","Foioasele își leapădă frunzele late ca să reziste iernii reci, iar coniferele, cu ace rezistente la ger, rămân verzi.","Fiindcă foioasele sunt copaci mult mai bătrâni, iar vârsta lor înaintată le usucă frunzele în fiecare iarnă.","Fiindcă animalele mănâncă acele coniferelor tocmai iarna, când nu mai găsesc altă hrană verde prin preajmă."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a06' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Fiindcă solul (cernoziomul) este prea sărac pentru copaci, deși este cel mai fertil sol de pe glob.","Fiindcă în stepă este mereu prea cald pentru arbori, chiar și în plină iarnă geroasă.","Fiindcă vântul puternic dezrădăcinează orice copac tânăr înainte ca acesta să apuce să crească.","Fiindcă precipitațiile (250–500 mm/an) sunt prea puține pentru pădure, dar ajung pentru ierburi."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a07' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Fiindcă ploile abundente din stepă aduc mereu minerale noi și hrănesc solul în profunzime.","Fiindcă provin din lave vulcanice vechi, bogate în minerale rămase după răcirea lor.","Fiindcă ierburile bogate lasă mult humus, iar clima relativ uscată nu îl spală în adânc.","Fiindcă sunt înghețate cea mai mare parte a anului, ceea ce oprește descompunerea materiei organice."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a08' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Este o greșeală de observație: mai multă ploaie înseamnă, în toate cazurile, un sol mai bun.","Ploaia multă spală substanțele hrănitoare din sol, pe când clima mai uscată a stepei le păstrează și adună humus.","Pentru că stepa se află mult mai aproape de Ecuator decât pădurea ecuatorială, ceea ce îi schimbă solul.","Pentru că în pădurea ecuatorială nu cresc deloc plante mari, ci doar licheni și mușchi rari."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a09' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Fiindcă deșerturile temperate din Asia Centrală au ierni foarte geroase, nu doar veri calde.","Fiindcă este o specie mult mai bătrână, apărută cu milioane de ani înaintea celei din Sahara.","Fiindcă în Gobi plouă abundent tot anul, iar umezeala rece o obligă să își îngroașe blana.","Fiindcă se hrănește numai cu zăpadă, iar blana groasă o ajută să reziste la atingerea gheții."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a10' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Fiindcă erbivorele care trec mereu pe acolo le pasc fără încetare, nelăsându-le timp să crească.","Fiindcă solul este mult prea fertil, iar plantele nu au nevoie să crească înalte după hrană.","Fiindcă primesc prea multă lumină în lunile de vară, ceea ce le oprește brusc creșterea în înălțime.","Fiindcă frigul, sezonul scurt de vegetație și solul înghețat în adâncime nu le permit să crească înalte."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a11' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Fiindcă vântul puternic de acolo îi rupe imediat ce răsar, oricât de bine ar fi înrădăcinați.","Fiindcă stratul de sol înghețat permanent (permafrost) împiedică rădăcinile adânci și scurgerea apei.","Fiindcă acolo este prea cald pentru copaci, iar seceta de vară le usucă rădăcinile firave.","Fiindcă lipsește complet lumina în tot cursul anului, chiar și în lunile scurte de vară."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a12' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Din lichenii și mușchii de pe uscat, singura hrană disponibilă pe continentul înghețat.","Din plante aduse de vânt din alte zone, purtate peste ocean până pe țărmurile Antarcticii.","Din ocean — bogăția vieții antarctice depinde de hrana din apă, nu de vegetația de uscat.","Nu se hrănesc deloc în timpul iernii, ci trăiesc numai din rezervele adunate vara."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a13' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Fiindcă Soarele încălzește inegal Pământul, mult la Ecuator și puțin la poli, schimbând clima cu latitudinea.","Fiindcă solurile sunt aranjate din natură în fâșii colorate, iar vegetația doar le urmează culoarea, an de an.","Fiindcă vânturile bat numai dinspre nord, purtând mereu aceleași semințe pe toată suprafața globului.","Fiindcă Pământul este mai vechi la poli decât la Ecuator, unde scoarța s-ar fi format mult mai recent."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a14' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Fiindcă, de fapt, la Ecuator este foarte frig tot timpul anului, chiar și la poalele muntelui.","Fiindcă zăpada este adusă cu vântul tocmai de la poli, până sus, pe vârful muntelui ecuatorial.","Fiindcă la Ecuator noaptea durează șase luni întregi, timp suficient ca zăpada să nu apuce să se topească.","Fiindcă temperatura scade cu altitudinea, iar pe verticală apar etaje asemănătoare zonelor de la Ecuator la poli."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a15' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Fiindcă este mult mai rece decât pădurea ecuatorială, iar frigul obligă arborii să își piardă frunzele.","Fiindcă are un sezon secetos (musonii aduc ploaie doar vara), iar în perioada uscată arborii își leapădă frunzele.","Fiindcă solul ei este nisipos și sărac, complet incapabil să hrănească frunzele tot parcursul anului.","Fiindcă primește ploi abundente tot timpul anului, exact la fel ca pădurea ecuatorială din vecinătate."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a16' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Precipitațiile foarte reduse — doar plantele adaptate la secetă (xerofite) pot trăi acolo.","Frigul, care este prea aspru pentru plante chiar și în deșerturile aflate în zona caldă.","Solul prea fertil, care îneacă rădăcinile plantelor obișnuite să crească în teren sărac.","Animalele, care mănâncă absolut toate plantele înainte ca acestea să apuce să înflorească."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a17' AND locale = 'ro';
UPDATE question_translations SET options_json = '["savană -> pădure ecuatorială -> tundră -> taiga, în ordinea depărtării de Ecuator","tundră -> taiga -> pădure de foioase -> pădure ecuatorială, pornind dinspre pol","pădure ecuatorială -> savană -> pădure de foioase -> taiga -> tundră","mediteraneană -> pădure ecuatorială -> savană -> tundră, în ordinea firească"]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a18' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Spre o pădure ecuatorială deasă, fiindcă orice încălzire aduce automat mai multă ploaie.","Spre o stepă cu ierburi, fiindcă precipitațiile mai puține nu ar mai susține pădurea.","Spre o tundră cu plante pitice, fiindcă frigul devine principalul factor limitativ.","Spre o taiga de conifere, fiindcă seceta favorizează în special copacii cu frunze-ace."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a19' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Pentru că toate zonele de pe glob au, în esență, aceleași plante și animale, doar denumite diferit.","Pentru că animalele își aleg singure clima preferată, migrând mereu acolo unde le convine mai bine.","Pentru că vegetația nu depinde în niciun fel de climă, ci numai de tipul de sol aflat dedesubt.","Pentru că clima determină vegetația, iar vegetația determină fauna și solul — toate sunt legate într-un lanț."]' WHERE question_id = '9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a20' AND locale = 'ro';

-- soluri_new.json
UPDATE question_translations SET options_json = '["Ambele sunt, de fapt, roca-mamă (orizontul C), doar cu grade diferite de umiditate și afânare.","Orizontul deschis este humusul acumulat de plante, iar cel închis este roca-mamă nealterată.","Orizontul închis este A (bioacumulativ, bogat în humus), iar cel deschis este E (eluvial, spălat de apă).","Ambele sunt orizontul B, cel de acumulare, doar cu cantități diferite de argilă depusă."]' WHERE question_id = 'c0f544c9-7af5-40fc-bfe5-ede8fd9a855f' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Au fost spălate de apă din orizonturile de deasupra și depuse (iluviate) aici, mai jos.","Au urcat din roca-mamă spre suprafață, purtate de apa care se evaporă prin capilaritate.","Au fost aduse de vânt de la suprafața solului și înfiltrate treptat printre particulele fine.","S-au format prin topirea repetată a gheții adunate în adâncul solului, de-a lungul iernilor."]' WHERE question_id = '0d41e677-1f7b-4a1f-9ed6-77088c8d1be2' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Pentru că roca-mamă este, de fapt, identică pe tot globul, indiferent de zona climatică.","Pentru că omul a arat solurile la fel peste tot, ștergând diferențele naturale dintre ele.","Pentru că timpul de formare este același pretutindeni, iar solul nu apucă să se diferențieze.","Pentru că clima este factorul pedogenetic cel mai important și hotărăște ce procese formează solul."]' WHERE question_id = 'de94d85b-91d9-46d6-896e-6d049e90112f' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Calcifierea, procesul care acumulează carbonat de calciu în sol, tipic climatelor secetoase.","Lateritizarea: căldura și apa multă spală bazele și silicea și lasă în urmă oxizi de fier și aluminiu roșiatici.","Podzolirea, procesul tipic al pădurilor de conifere dintr-un climat răcoros și foarte umed, de munte.","Înghețul repetat, care sfărâmă mecanic roca-mamă fără să schimbe compoziția chimică a solului."]' WHERE question_id = '56087188-bd6e-4764-8a49-fd140081009f' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Lateritizarea, specifică unui climat cald și foarte umed, cu ploi abundente tot timpul anului.","Podzolirea, specifică unui climat răcoros și ploios, sub pădurile de conifere din nord.","Calcifierea, într-un climat secetos, unde evaporația mare împiedică apa să spele solul în adânc.","Gleizarea, specifică locurilor joase și băltite, unde solul rămâne lipsit de oxigen."]' WHERE question_id = '04dadcd1-c336-4751-9755-5b7cf1063f05' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Podzolirea: apa spală argila, humusul și fierul din orizontul superior și le depune mai jos.","Calcifierea: acumularea carbonatului de calciu la suprafață, într-un climat secetos și cald.","Lateritizarea: acumularea oxizilor roșii de fier și aluminiu, într-un climat cald și umed.","Salinizarea: acumularea sărurilor minerale la suprafața solului, în zonele foarte secetoase."]' WHERE question_id = '80a4046a-baa1-4fde-875d-d3c27f241e78' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Culoarea solului, care arată doar cantitatea de humus, nu viteza de scurgere a apei prin el.","Textura, dată de mărimea particulelor: nisipul are pori largi, apa trece ușor; argila o reține.","pH-ul solului, adică reacția lui chimică, acidă, neutră sau bazică, indiferent de textură.","Cantitatea de humus din sol, care ține de fertilitate, nu de viteza de scurgere a apei."]' WHERE question_id = '10a8dfb6-bf1b-480d-92f8-43ca02b42e30' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Roca-mamă (materialul parental), din care provine partea minerală a solului.","Timpul, deoarece unul dintre soluri s-a format cu mult mai devreme decât celălalt.","Omul, prin agricultura practicată diferit pe cele două parcele de teren învecinate.","Relieful, prin panta diferită a celor două parcele aflate una lângă cealaltă."]' WHERE question_id = '2b61a73d-8a08-479c-a0b8-e89daea65d08' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Vegetația, care dă materia organică din frunze și rădăcini, ce se transformă apoi în humus.","Apa, care doar dizolvă substanțele minerale, fără să lase materie organică în sol.","Relieful, care hotărăște panta terenului și viteza cu care se scurge apa de ploaie.","Roca-mamă, care oferă doar partea minerală a solului, nu și materia organică."]' WHERE question_id = '23e4b32e-7c08-46f4-8f1c-529a00a7ad19' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Primul este orizontul E (eluvial, spălat), al doilea orizontul B (de acumulare).","Primul este orizontul O (litiera), al doilea, orizontul A (bioacumulativ).","Primul este orizontul C (materialul parental), al doilea orizontul R (roca dură).","Primul este orizontul B (de acumulare), al doilea orizontul O (litiera de suprafață)."]' WHERE question_id = '6c3f94c2-1aa0-43a7-a638-9962b8c60e9c' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Materialul parental (orizontul C) și roca parentală compactă (orizontul R).","Orizontul A (bioacumulativ) și orizontul E (eluvial, spălat de apă și de minerale).","Orizontul gleic (băltit) și orizontul turbos (din resturi vegetale slab descompuse).","Orizontul B (de acumulare) și orizontul O (litiera de la suprafața solului)."]' WHERE question_id = 'fd98ad43-527e-4de0-be0b-27cce5fd7155' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Orizontul turbos, din resturi vegetale slab descompuse, în locuri reci și umede.","Orizontul C, materialul parental slab consolidat, aflat sub toate celelalte orizonturi.","Orizontul A, bioacumulativ obișnuit, prezent aproape peste tot, în orice climat temperat.","Orizontul R, roca parentală dură și neafectată, aflată la baza întregului profil de sol."]' WHERE question_id = 'e97a8b73-27c5-419f-95d6-87bfddf376a2' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Ambele descrieri se referă, de fapt, la structură, doar exprimată în cuvinte diferite.","Prima se referă la structură (felul în care se leagă particulele), a doua la textură (mărimea lor).","Prima se referă la fertilitatea solului, a doua la culoarea lui, nu la structură.","Ambele descrieri se referă, de fapt, la textură, doar exprimată prin cuvinte diferite."]' WHERE question_id = 'f2807874-db51-4ce5-8a21-88c40382af47' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Primul măsoară fertilitatea solului, al doilea doar culoarea particulelor din el.","Primul măsoară pH-ul, adică reacția chimică a solului, al doilea permeabilitatea lui.","Amândoi măsoară, de fapt, aceeași proprietate: textura, dată de mărimea particulelor.","Primul măsoară structura solului, al doilea doar porozitatea lui, nu compoziția chimică."]' WHERE question_id = '2273be24-5730-45cb-aa2e-a45dd21aadf2' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Clima, care este identică în cele două zone învecinate, aflate la aceeași altitudine.","Timpul: solurile mature se formează în mii de ani, iar suprafața recent expusă n-a avut încă timp.","Roca-mamă, care nu influențează deloc viteza de formare a unui profil de sol matur.","Vegetația, care este identică în cele două zone și crește la fel de repede peste tot."]' WHERE question_id = '16afe5ef-2929-4e46-b12f-579d0116c2f9' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Omul, care prin agricultura intensivă poate îmbunătăți solul sau, dimpotrivă, îl poate distruge.","Relieful, care rămâne mereu neschimbat, oricât de intensă ar fi activitatea umană.","Timpul, singurul factor implicat, întrucât solul e prea tânăr ca să fi fost afectat.","Apa freatică, singurul factor implicat, prin urcarea și coborârea ei repetată."]' WHERE question_id = '9d1151f9-03d0-4e00-8879-79ad76a6326e' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Structura, felul în care particulele solului se leagă între ele în agregate mai mari.","Fertilitatea, capacitatea solului de a hrăni plantele, cea mai importantă însușire a lui.","Porozitatea, spațiile goale dintre particulele solului prin care circulă apa și aerul.","pH-ul, reacția chimică a solului, care arată dacă acesta este acid, neutru sau bazic."]' WHERE question_id = 'c068bdd8-320e-4cc7-b1ba-81bed2600285' AND locale = 'ro';
UPDATE question_translations SET options_json = '["Calcifierea: acumularea carbonatului de calciu, specifică unui climat mult mai secetos.","Lateritizarea: îndepărtarea bazelor și silicei, specifică unui climat cald și tropical.","Podzolirea: spălarea argilei și a compușilor de fier și aluminiu din orizontul superior spre cel inferior.","Salinizarea: acumularea sărurilor la suprafață, specifică zonelor secetoase și joase."]' WHERE question_id = '724beafd-3c1a-4901-8617-5321792b5fbb' AND locale = 'ro';
UPDATE question_translations SET options_json = '["În stepă, ierburile lasă mult humus, pe când în deșert vegetația e rară și humusul aproape lipsește.","În deșert plouă, de fapt, mai mult decât în stepă, deși ambele sunt zone secetoase.","Cernoziomul se formează doar prin lateritizare, nu prin acumularea humusului din ierburi.","Aridisolul are, de fapt, mai mult humus acumulat în adânc decât cernoziomul de stepă însuși."]' WHERE question_id = 'd49d15dc-9214-490a-a74b-1b1f98eecd09' AND locale = 'ro';

